// Diamond hierarchy: Stream <- BufferedStream <- BiDiBufferedStream
//                            <- LoggingStream   <-
// Without `virtual` on the base, both BufferedStream and LoggingStream
// carry their own Stream sub-object — flush() in the derived class is
// ambiguous and the compiler rejects the call.
#include <iostream>

struct Stream {
    virtual void flush() = 0;
    virtual ~Stream() = default;
};

struct BufferedStream : public Stream {
    void flush() override { std::cout << "buffered\n"; }
};

struct LoggingStream : public Stream {
    void flush() override { std::cout << "logging\n"; }
};

// Bug: should inherit virtually from Stream to avoid the diamond.
struct BiDiBufferedStream : public BufferedStream, public LoggingStream {
    // Caller has to disambiguate: BufferedStream::flush() vs LoggingStream::flush().
    void flush() override { BufferedStream::flush(); LoggingStream::flush(); }
};
